from pathlib import Path
import shutil,re,json,subprocess
root=Path('/tmp/gma-bottosson-investigation-be03abd');repo=Path('/home/lloydk/work/gma-benchmark')
source=(root/'current/src/bottosson-factory.js').read_text()
def body(text,name):
 start=text.index('function '+name+' ('); opening=text.index('{',start);depth=1;i=opening+1
 while depth:
  if text[i]=='{':depth+=1
  elif text[i]=='}':depth-=1
  i+=1
 return text[opening+1:i-1]
def replace(text,old,new,count=1):
 assert text.count(old)==count,(old,text.count(old));return text.replace(old,new)
def intersection(s):
 b=body(source,'findGamutIntersectionQ').replace('\n\t\tlet t;','',1).replace('\n\t\treturn t;','')
 args=['q0','q1','q2','l1','c1','l0','cuspL','cuspC']
 for x in args:b=re.sub(r'\b'+x+r'\b','arg_'+x,b)
 pattern=r'const t = findGamutIntersectionQ\(([^;]+)\);'
 def inline(m):
  exprs=m[1].split(', ');assert len(exprs)==8
  return 'let t;\n\t\t{\n'+''.join(f'\t\tconst arg_{name} = {expr};\n' for name,expr in zip(args,exprs))+b+'\n\t\t}'
 s,n=re.subn(pattern,inline,s);assert n==2
 return s
def saturation(s):
 b=body(source,'computeMaxSaturationRgb').replace('return sat -','sCusp = sat -')
 return replace(s,'const sCusp = computeMaxSaturationRgb(a, b, h);','let sCusp;\n\t\t{'+b+'\n\t\t}')
precheck=body((repo/'src/rgb-convert.js').read_text(),'oklchToRgbIfInGamut')
prefix=precheck[:precheck.index('\n\t\tif (!(')]
prefix=prefix.replace('const a = C *','const a = oklch[1] *').replace('const b = C *','const b = oklch[1] *')
check=prefix+'''\n\t\tif (r >= 0 && r <= 1 && g >= 0 && g <= 1 && bl >= 0 && bl <= 1) {
            out[0] = clampedGamma(r); out[1] = clampedGamma(g); out[2] = clampedGamma(bl);
            return out;
        }'''
def inline_precheck(s):
 return replace(s,'if (checkInGamut && oklchToRgbIfInGamut(L, oklch[1], H, out)) return out;','if (checkInGamut) {'+check+'\n\t\t}',2)
def no_guard(s):
 b=body(s,'sector');start=s.index('function sector (');pos=s.index(b,start)
 return s[:pos]+'''\n        return a * RED1 + b * RED2 > 1 ? 0 : a * GREEN1 + b * GREEN2 > 1 ? 1 : 2;
    '''+s[pos+len(b):]
def literals(s):
 script="import {DISPLAY_P3 as p} from './src/rgb-spaces.js';import {bottossonFits} from './src/generated/bottosson.js';console.log(JSON.stringify({p,d:bottossonFits[p.id]}));"
 dat=json.loads(subprocess.check_output(['node','--input-type=module','-e',script],cwd=root/'current',text=True));p,d=dat['p'],dat['d']
 names=dict(zip(['KA0','KB0','KA1','KB1','KA2','KB2'],[v for row in p['oklabToLms'] for v in row[1:]]))
 names.update(zip(['RL','RM','RS','GL','GM','GS','BL','BM','BS'],sum(p['lmsToRgb'],[])))
 names.update(zip(['RED1','RED2','GREEN1','GREEN2'],d['red']+d['green']))
 for ch,vals in zip(['RED','GREEN','BLUE'],d['fits']):names.update({f'{ch}_K{i}':v for i,v in enumerate(vals)})
 s=re.sub(r'\tconst \[\[, KA0.*?space.oklabToLms;\n','',s)
 s=re.sub(r'\tconst \[\[RL.*?space.lmsToRgb;\n','',s)
 s=re.sub(r'\tconst \[RED1.*?data.red;\n','',s)
 s=re.sub(r'\tconst \[GREEN1.*?data.green;\n','',s)
 s=re.sub(r'\tconst \[\[RED_K0.*?data.fits;\n','',s,flags=re.S)
 for k,v in names.items():s=re.sub(r'\b'+k+r'\b',f'({v!r})',s)
 return s
variants={
 'inline-precheck':inline_precheck(source),
 'inline-intersection':intersection(source),
 'inline-saturation':saturation(source),
 'inline-math':saturation(intersection(source)),
 'inline-all':inline_precheck(saturation(intersection(source))),
 'literal-coefficients':literals(source),
 'no-contact-guard':no_guard(source),
 'legacy-radian-order':source.replace('H * Math.PI / 180','H * (Math.PI / 180)'),
}
for name,s in variants.items():
 dest=root/name;shutil.copytree(root/'current',dest,symlinks=True)
 (dest/'src/bottosson-factory.js').write_text(s)
 subprocess.run(['node','--check',dest/'src/bottosson-factory.js'],check=True)
print('Built:',list(variants))

