from pathlib import Path
import shutil,subprocess
root=Path('/tmp/gma-bottosson-investigation-be03abd')
s=(root/'current/src/bottosson-factory.js').read_text()
def reuse(s):
 i=s.index('function bottossonLightness (');before,mapper=s[:i],s[i:]
 old='if (checkInGamut && oklchToRgbIfInGamut(L, oklch[1], H, out)) return out;'
 new='''let unitA, unitB;
        if (checkInGamut) {
            const hr = H * Math.PI / 180;
            unitA = Math.cos(hr); unitB = Math.sin(hr);
            const a = oklch[1] * unitA, b = oklch[1] * unitB;
            const l0 = L + KA0 * a + KB0 * b;
            const m0 = L + KA1 * a + KB1 * b;
            const s0 = L + KA2 * a + KB2 * b;
            const l = l0*l0*l0, m = m0*m0*m0, s = s0*s0*s0;
            const r = RL*l + RM*m + RS*s;
            const g = GL*l + GM*m + GS*s;
            const bl = BL*l + BM*m + BS*s;
            if (r >= 0 && r <= 1 && g >= 0 && g <= 1 && bl >= 0 && bl <= 1) {
                out[0]=clampedGamma(r); out[1]=clampedGamma(g); out[2]=clampedGamma(bl);
                return out;
            }
        }'''
 assert mapper.count(old)==1;mapper=mapper.replace(old,new)
 old='''const hRad = H * Math.PI / 180;
		const unitA = Math.cos(hRad);
		const unitB = Math.sin(hRad);'''
 new='''if (!checkInGamut) {
            const hRad = H * Math.PI / 180;
            unitA = Math.cos(hRad); unitB = Math.sin(hRad);
        }'''
 assert mapper.count(old)==1;return before+mapper.replace(old,new)
variants={'reuse-trig':reuse(s),'reuse-and-intersection':reuse((root/'inline-intersection/src/bottosson-factory.js').read_text()),'reuse-and-math':reuse((root/'inline-math/src/bottosson-factory.js').read_text())}
# Diagnostic only: restore cache-hue membership while retaining current mapper math.
i=s.index('function bottossonLightnessCached (');j=s.index('function bottossonLightness (');mapper=s[i:j]
mapper=mapper.replace('if (checkInGamut && oklchToRgbIfInGamut(L, oklch[1], H, out)) return out;','')
marker='const q2 = cuspCache[k + 4];'
old=(root/'original/src/bottosson-lightness.js').read_text()
a=old.index('function lmsSlopesToP3IfInGamut (');b=old.index('// `oklch`',a)
helper=old[a:b]
mapper=mapper.replace(marker,marker+'\nif (checkInGamut && lmsSlopesToP3IfInGamut(L,C,q0,q1,q2,out)) return out;')
variants['quantized-precheck']=s[:i]+helper+mapper+s[j:]
for name,text in variants.items():
 dest=root/name;shutil.copytree(root/'current',dest,symlinks=True)
 (dest/'src/bottosson-factory.js').write_text(text)
 subprocess.run(['node','--check',dest/'src/bottosson-factory.js'],check=True)
print(list(variants))

