from pathlib import Path
import subprocess,shutil,json,re,statistics
root=Path('/tmp/gma-bottosson-investigation-be03abd')
r={'description':'ABBA current/candidate/candidate/current, same path, fresh serial processes, CPU 2, unchanged full 13-method P3 harness, 50 warmup passes, Node --expose-gc; no concurrent validation/profiling/builds. Candidate is reuse-and-math.','runs':[]}
for position,variant in enumerate(['current','reuse-and-math','reuse-and-math','current']):
 dest=root/'timed'
 if dest.exists():shutil.rmtree(dest)
 shutil.copytree(root/variant,dest,symlinks=True)
 for rt in ['node','bun']:
  for checked in [False,True]:
   command=['taskset','-c','2',rt,*(['--expose-gc'] if rt=='node' else []),'bench.js','--timing-only',*(['--in-gamut-check'] if checked else [])]
   log=subprocess.check_output(command,cwd=dest,text=True,stderr=subprocess.STDOUT)
   (root/f'full-{position}-{variant}-{rt}-{checked}.log').write_text(log)
   clean=re.sub(r'\x1b\[[0-9;]*m','',log);rows=[]
   for m in re.finditer(r'^(.+?)\s+([\d.]+)\s+(ns|µs|us|ms|s)/iter',clean,re.M):
    name=m[1].strip().removeprefix('display-p3 / ');random=name.endswith(' (random hues)')
    if random:name=name.removesuffix(' (random hues)')
    rows.append({'method':name,'workload':'random' if random else 'grid','ns':float(m[2])*{'ns':1,'µs':1e3,'us':1e3,'ms':1e6,'s':1e9}[m[3]]/35640})
   assert len(rows)==26
   r['runs'].append({'position':position,'variant':variant,'runtime':rt,'checked':checked,'rows':rows,'command':command,'log':log})
   (root/'full.json').write_text(json.dumps(r,indent=2)+'\n')
   print(position,variant,rt,checked,flush=True)
r['summary']=[]
for rt in ['node','bun']:
 for checked in [False,True]:
  for method in ['bottosson-lightness','bottosson-lightness (cached)']:
   for w in ['grid','random']:
    vals=[[v['ns'] for run in r['runs'] if run['runtime']==rt and run['checked']==checked and run['variant']==variant for v in run['rows'] if v['method']==method and v['workload']==w] for variant in ['current','reuse-and-math']]
    b,a=map(statistics.median,vals)
    r['summary'].append(dict(runtime=rt,checked=checked,method=method,workload=w,beforeNs=b,afterNs=a,percent=100*(a/b-1),beforeProcesses=vals[0],afterProcesses=vals[1]))
(root/'full.json').write_text(json.dumps(r,indent=2)+'\n')
print('Done',flush=True)

