import assert from 'node:assert/strict';
import {pathToFileURL} from 'node:url';
import {buildWorkloads} from '/home/lloydk/work/gma-benchmark/benchmark-workloads.js';
import {bottossonSamples} from '/home/lloydk/work/gma-benchmark/tests/helpers/bottosson-samples.js';
const root='/tmp/gma-bottosson-investigation-be03abd';
const variants=process.argv.slice(2);
const {samples,randomSamples}=buildWorkloads();
const records=[];
async function load(name,id){
 const {getRgbSpace}=await import(pathToFileURL(`${root}/${name}/src/rgb-spaces.js`));
 const {createBottossonMappers}=await import(pathToFileURL(`${root}/${name}/src/bottosson-factory.js`));
 return createBottossonMappers(getRgbSpace(id));
}
for(const variant of variants)for(const gamut of ['display-p3','srgb','rec2020']){
 const inputs=[...samples,...randomSamples,...bottossonSamples(gamut)];
 const before=await load('current',gamut),after=await load(variant,gamut);
 for(const method of Object.keys(before))for(const checked of [false,true]){
  const a=[],b=[];let changed=0,max=0,worst=null;
  const oldMap=checked?(v,o)=>before[method](v,o,true):before[method];
  const newMap=checked?(v,o)=>after[method](v,o,true):after[method];
  for(const input of inputs){
   a.length=b.length=3;a.fill(NaN);b.fill(NaN);
   assert.equal(oldMap(input,a),a);assert.equal(newMap(input,b),b);
   if(a.some((v,i)=>!Object.is(v,b[i])))changed++;
   for(let i=0;i<3;i++){
    assert(Number.isFinite(a[i])&&Number.isFinite(b[i]));
    const err=Math.abs(a[i]-b[i]);if(err>max){max=err;worst=input;}
   }
   const alias=[...input];assert.equal(newMap(alias,alias),alias);assert.deepEqual(alias,b);
  }
  records.push({variant,gamut,method,checked,count:inputs.length,changed,max,worst});
 }
}
console.log(JSON.stringify({runtime:process.versions,records}));

