	}

	// LMS'-slope conversion: LMS'ᵢ = L + C·qᵢ.
	function lmsSlopesToClippedRgb (L, C, q0, q1, q2, out) {
		const l0 = L + C * q0;
		const m0 = L + C * q1;
		const s0 = L + C * q2;
		const l = l0 * l0 * l0;
		const m = m0 * m0 * m0;
		const s = s0 * s0 * s0;
		out[0] = clampedGamma(RL * l + RM * m + RS * s);
		out[1] = clampedGamma(GL * l + GM * m + GS * s);
