		const sCusp = computeMaxSaturationRgb(a, b, h);
		const l = 1 + sCusp * (KA0 * a + KB0 * b);
		const m = 1 + sCusp * (KA1 * a + KB1 * b);
		const s = 1 + sCusp * (KA2 * a + KB2 * b);
