		let k0, k1, k2, k3, k4;
		let wl, wm, ws;

		const channel = sector(a, b, h);
		if (channel === 0) {
			k0 = RED_K0;
			k1 = RED_K1;
			k2 = RED_K2;
			k3 = RED_K3;
			k4 = RED_K4;
