		let k0, k1, k2, k3, k4;
		let wl, wm, ws;

		const channel = sector(a, b, h);
		if (channel === 0) {
			k0 = RED_K0;
			k1 = RED_K1;
			k2 = RED_K2;
			k3 = RED_K3;
			k4 = RED_K4;
			wl = RL;
			wm = RM;
			ws = RS;
		}
		else if (channel === 1) {
			k0 = GREEN_K0;
			k1 = GREEN_K1;
			k2 = GREEN_K2;
			k3 = GREEN_K3;
			k4 = GREEN_K4;
			wl = GL;
			wm = GM;
			ws = GS;
		}
		else {
			k0 = BLUE_K0;
			k1 = BLUE_K1;
			k2 = BLUE_K2;
			k3 = BLUE_K3;
			k4 = BLUE_K4;
			wl = BL;
			wm = BM;
			ws = BS;
		}

