		const m3 = m * m * m;
		const s3 = s * s * s;
		const r = RL * l3 + RM * m3 + RS * s3;
		const g = GL * l3 + GM * m3 + GS * s3;
		const blue = BL * l3 + BM * m3 + BS * s3;
