		const arg_c1 = C;
		const arg_l0 = L0;
		const arg_cuspL = cuspL;
		const arg_cuspC = cuspC;


		if ((arg_l1 - arg_l0) * arg_cuspC - (arg_cuspL - arg_l0) * arg_c1 <= 0) {
