			const mdtBase = dl + arg_c1 * arg_q1;
			const sdtBase = dl + arg_c1 * arg_q2;
			const L = arg_l0 + t * (arg_l1 - arg_l0);
			const C = t * arg_c1;
			const l = L + C * arg_q0;
			const m = L + C * arg_q1;
			const s = L + C * arg_q2;
			const l2 = l * l;
			const m2 = m * m;
			const s2 = s * s;
			const l3 = l2 * l;
			const m3 = m2 * m;
			const s3 = s2 * s;
