			const mdt = 3 * mdtBase * m2;
			const sdt = 3 * sdtBase * s2;
			const ldt2 = 6 * ldtBase * ldtBase * l;
			const mdt2 = 6 * mdtBase * mdtBase * m;
			const sdt2 = 6 * sdtBase * sdtBase * s;

